    #[test]
    fn fabrication_authorization_report_rendering_is_newline_terminated_and_bounded() {
        let report = sample_fabrication_authorization_report();
        let rendered = render_fabrication_authorization_report(&report).unwrap();
        assert!(rendered.ends_with(b"\n"));
        assert!(rendered.len() as u64 <= fs::MAX_FILE_BYTES);
        assert_eq!(
            rendered,
            format!("{}\n", serde_json::to_string_pretty(&report).unwrap()).as_bytes()
        );
        assert_eq!(
            serde_json::from_slice::<FabricationAuthorizationReport>(&rendered).unwrap(),
            report
        );

        let exact =
            render_fabrication_authorization_report_with_limit(&report, rendered.len() as u64)
                .unwrap();
        assert_eq!(exact, rendered);
        let error =
            render_fabrication_authorization_report_with_limit(&report, rendered.len() as u64 - 1)
                .unwrap_err();
        assert!(format!("{error:#}").contains("file limit"), "{error:#}");
    }

    #[cfg(unix)]
    #[test]
    fn reservation_commit_time_is_inclusive_without_rewriting_report_time() {
        let report = sample_fabrication_authorization_report();
        assert_eq!(report.evaluated_at_unix, 150);
        validate_fabrication_authorization_reservation_commit_time(&report, 100).unwrap();
        validate_fabrication_authorization_reservation_commit_time(&report, 200).unwrap();
        assert!(validate_fabrication_authorization_reservation_commit_time(&report, 99).is_err());
        assert!(validate_fabrication_authorization_reservation_commit_time(&report, 201).is_err());
        assert_eq!(report.evaluated_at_unix, 150);
    }

    #[cfg(unix)]
    #[test]
    fn reservation_completion_time_burns_a_durably_committed_expired_challenge() {
        let report = sample_fabrication_authorization_report();
        finish_fabrication_authorization_reservation(
            &report,
            anchored_io::NoReplacePublicationOutcome::CommittedDurable,
            || Ok(200),
        )
        .unwrap();

        let expired = finish_fabrication_authorization_reservation(
            &report,
            anchored_io::NoReplacePublicationOutcome::CommittedDurable,
            || Ok(201),
        )
        .unwrap_err();
        let message = format!("{expired:#}");
        assert!(message.contains("committed durably"), "{message}");
        assert!(message.contains("challenge remains reserved"), "{message}");

        let clock_failure = finish_fabrication_authorization_reservation(
            &report,
            anchored_io::NoReplacePublicationOutcome::CommittedDurable,
            || bail!("injected clock failure"),
        )
        .unwrap_err();
        let message = format!("{clock_failure:#}");
        assert!(message.contains("completion-time clock"), "{message}");
        assert!(message.contains("challenge remains reserved"), "{message}");
    }

    #[test]
    fn fabrication_authorization_summary_is_path_free_closed_and_ordered() {
        let report = sample_fabrication_authorization_report();
        let rendered = render_fabrication_authorization_report(&report).unwrap();
        let summary_bytes =
            render_fabrication_authorization_report_summary(&report, &rendered).unwrap();
        assert_eq!(
            summary_bytes.iter().filter(|byte| **byte == b'\n').count(),
            1
        );
        assert_eq!(summary_bytes.last(), Some(&b'\n'));
        let compact = std::str::from_utf8(&summary_bytes[..summary_bytes.len() - 1]).unwrap();
        let value: serde_json::Value = serde_json::from_str(compact).unwrap();
        let report_sha256 = hex::encode(Sha256::digest(&rendered));
        assert_eq!(
            value,
            serde_json::json!({
                "schema_version": 1,
                "status": "not_authorized",
                "fabrication_authorized": false,
                "authorization_id": "fab-summary",
                "challenge": "challenge",
                "quantity": 25,
                "currency": "USD",
                "maximum_total_minor_units": 125_000,
                "valid_from_unix": 100,
                "expires_at_unix": 200,
                "evaluated_at_unix": 150,
                "approvals": 1,
                "rejections": 1,
                "gate_failure_count": 2,
                "plan_sha256": "plan",
                "run_sha256": "run",
                "manufacturing_package_sha256": "package",
                "factory_receipt_sha256": "receipt",
                "policy_pack_sha256": "policy-source",
                "quote_authenticity_verified": false,
                "challenge_one_time_use_enforced": false,
                "report_bytes": rendered.len() as u64,
                "report_sha256": report_sha256,
            })
        );
        assert_eq!(value.as_object().unwrap().len(), 23);
        assert!(!compact.contains("path"));

        let fields = [
            "schema_version",
            "status",
            "fabrication_authorized",
            "authorization_id",
            "challenge",
            "quantity",
            "currency",
            "maximum_total_minor_units",
            "valid_from_unix",
            "expires_at_unix",
            "evaluated_at_unix",
            "approvals",
            "rejections",
            "gate_failure_count",
            "plan_sha256",
            "run_sha256",
            "manufacturing_package_sha256",
            "factory_receipt_sha256",
            "policy_pack_sha256",
            "quote_authenticity_verified",
            "challenge_one_time_use_enforced",
            "report_bytes",
            "report_sha256",
        ];
        let positions = fields.map(|field| {
            compact
                .find(&format!("\"{field}\":"))
                .unwrap_or_else(|| panic!("missing summary field {field}"))
        });
        assert!(positions.windows(2).all(|pair| pair[0] < pair[1]));
    }

