    fn procurement_output_publication_rejects_parent_replacement() {
        let directory = tempfile::tempdir().unwrap();
        let parent = directory.path().join("output-parent");
        let moved = directory.path().join("moved-parent");
        std::fs::create_dir(&parent).unwrap();
        let output = parent.join("output.json");
        let prepared = prepare_procurement_helper_output(&output, &[]).unwrap();
        std::fs::rename(&parent, &moved).unwrap();
        std::fs::create_dir(&parent).unwrap();
        assert!(persist_procurement_helper_output(prepared, &output, b"new\n").is_err());
        assert!(!output.exists());
        assert!(!moved.join("output.json").exists());
    }

    #[test]
    fn parses_closed_local_fabrication_authorization_reservation_surface() {
        let ledger_id = "12".repeat(32);
        let parsed = parse_cli(&[
            "pcbex",
            "reserve-fabrication-authorization",
            "--report",
            "pipeline-report.json",
            "--manufacturing-package",
            "manufacturing.zip",
            "--factory-receipt",
            "factory-receipt.json",
            "--policy-pack",
            "policy-pack.json",
            "--approval",
            "approval-a.json",
            "--approval",
            "approval-b.json",
            "--reservation-ledger",
            "/private/fabrication-ledger",
            "--expected-ledger-id",
            &ledger_id,
            "--",
            "plan.json",
        ])
        .unwrap();
        assert!(matches!(
            *parsed.command,
            Command::ReserveFabricationAuthorization {
                approvals,
                reservation_ledger,
                expected_ledger_id,
                plan,
                ..
            } if approvals.len() == 2
                && reservation_ledger.as_os_str() == "/private/fabrication-ledger"
                && expected_ledger_id == ledger_id
                && plan.as_os_str() == "plan.json"
        ));

        let (long_options, positional_ids) = std::thread::Builder::new()
            .stack_size(32 * 1024 * 1024)
            .spawn(|| {
                let mut command = Cli::command();
                let command = command
                    .find_subcommand_mut("reserve-fabrication-authorization")
                    .unwrap();
                let long_options = command
                    .get_arguments()
                    .filter_map(|argument| argument.get_long())
                    .filter(|name| *name != "help")
                    .map(str::to_string)
                    .collect::<Vec<_>>();
                let positional_ids = command
                    .get_positionals()
                    .map(|argument| argument.get_id().as_str().to_string())
                    .collect::<Vec<_>>();
                (long_options, positional_ids)
            })
            .unwrap()
            .join()
            .unwrap();
        assert_eq!(
            long_options,
            [
                "report",
                "manufacturing-package",
                "factory-receipt",
                "policy-pack",
                "approval",
                "reservation-ledger",
                "expected-ledger-id",
            ]
        );
        assert_eq!(positional_ids, ["plan"]);
    }

    #[test]
    fn reservation_parser_requires_separator_and_lowercase_ledger_id() {
        let ledger_id = "34".repeat(32);
        let base = [
            "pcbex",
            "reserve-fabrication-authorization",
            "--report",
            "pipeline-report.json",
            "--manufacturing-package",
            "manufacturing.zip",
            "--factory-receipt",
            "factory-receipt.json",
            "--policy-pack",
            "policy-pack.json",
            "--approval",
            "approval.json",
            "--reservation-ledger",
            "/private/fabrication-ledger",
            "--expected-ledger-id",
        ];
        let mut missing_separator = base.to_vec();
        missing_separator.extend([ledger_id.as_str(), "plan.json"]);
        assert!(parse_cli(&missing_separator).is_err());

        for invalid in ["ab", &"A5".repeat(32), &"g0".repeat(32)] {
            let mut arguments = base.to_vec();
            arguments.extend([invalid, "--", "plan.json"]);
            assert!(
                parse_cli(&arguments).is_err(),
                "accepted ledger id {invalid}"
            );
        }
    }

