    #[test]
    fn rejects_invalid_native_erc_replay_timeouts() {
        for value in [
            "0",
            "-0",
            "-1",
            "NaN",
            "inf",
            "600.000001",
            "1e999",
            "0.0000000001",
        ] {
            let option = format!("--timeout-seconds={value}");
            let result = parse_cli(&[
                "pcbex",
                "verify-native-kicad-erc-report",
                "input.kicad_sch",
                "erc.json",
                &option,
            ]);
            let error = match result {
                Ok(_) => panic!("invalid timeout {value:?} was accepted"),
                Err(error) => error,
            };
            assert!(
                error
                    .to_string()
                    .contains("representable as a positive Duration and at most 600 seconds"),
                "unexpected error for {value:?}: {error}"
            );
        }
    }

